-- Inventory Intelligence analytical data mart (AI database only; never the transactional DSports database).
-- EVERY row carries data_source:
--   POC_SYNTHETIC  generated by app.inventory.generator (deterministic, labelled, NOT real business history)
--   POC_REFERENCE  reference data DSports does not hold yet (cost, supplier, lead time, MOQ, regions), assumed for the POC
--   DSPORTS_LIVE   read from the DSports public REST APIs (catalogue, price, available stock)
-- Rebuildable: `python -m app.inventory.cli seed` + `train` recreate everything here.

CREATE TABLE IF NOT EXISTS inv_sku (
    product_id          UUID PRIMARY KEY,
    sku                 TEXT        NOT NULL,
    name                TEXT        NOT NULL,
    sport               TEXT        NOT NULL,
    category            TEXT        NOT NULL,
    brand               TEXT,
    price               NUMERIC(12,2) NOT NULL,          -- DSPORTS_LIVE selling price at the last refresh
    mrp                 NUMERIC(12,2),
    cost                NUMERIC(12,2),                   -- POC_REFERENCE: DSports has no cost data
    supplier            TEXT,                            -- POC_REFERENCE
    lead_time_days      INTEGER,                         -- POC_REFERENCE (NULL = unknown => no replenishment advice)
    moq                 INTEGER,                         -- POC_REFERENCE
    case_pack           INTEGER,                         -- POC_REFERENCE
    dsports_available   INTEGER,                         -- DSPORTS_LIVE sellable stock (reference only)
    data_source         TEXT        NOT NULL DEFAULT 'POC_REFERENCE',
    refreshed_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS inv_region (
    code        TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    data_source TEXT NOT NULL DEFAULT 'POC_REFERENCE'
);

CREATE TABLE IF NOT EXISTS inv_event (
    id          TEXT PRIMARY KEY,
    name        TEXT        NOT NULL,
    event_type  TEXT        NOT NULL,                    -- tournament | marathon | olympics | world_cup | regional
    sport       TEXT        NOT NULL,
    start_date  DATE        NOT NULL,
    end_date    DATE        NOT NULL,
    popularity  NUMERIC(6,2) NOT NULL DEFAULT 1.0,       -- relative size of the event (1.0 = a typical one); an input, not a result
    regions     JSONB       NOT NULL DEFAULT '{}'::jsonb, -- {region_code: relative weight}
    data_source TEXT        NOT NULL DEFAULT 'POC_REFERENCE'
);

CREATE TABLE IF NOT EXISTS inv_demand_daily (
    product_id   UUID    NOT NULL,
    region       TEXT    NOT NULL,
    day          DATE    NOT NULL,
    units        INTEGER NOT NULL,
    unit_price   NUMERIC(12,2) NOT NULL,
    discount_pct NUMERIC(5,2)  NOT NULL DEFAULT 0,
    event_id     TEXT,
    stockout     BOOLEAN NOT NULL DEFAULT FALSE,          -- demand was cut by lack of stock: the day under-states real demand
    data_source  TEXT    NOT NULL DEFAULT 'POC_SYNTHETIC',
    PRIMARY KEY (product_id, region, day)
);
CREATE INDEX IF NOT EXISTS ix_inv_demand_day ON inv_demand_daily (day);

CREATE TABLE IF NOT EXISTS inv_stock_snapshot (
    product_id  UUID    NOT NULL,
    region      TEXT    NOT NULL,
    day         DATE    NOT NULL,
    on_hand     INTEGER NOT NULL,
    incoming    INTEGER NOT NULL DEFAULT 0,
    data_source TEXT    NOT NULL DEFAULT 'POC_SYNTHETIC',
    PRIMARY KEY (product_id, region, day)
);

-- The CURRENT planning position (what the assessments use). age_days = age of the OLDEST units still on hand (FIFO).
CREATE TABLE IF NOT EXISTS inv_position (
    product_id       UUID    NOT NULL,
    region           TEXT    NOT NULL,
    on_hand          INTEGER NOT NULL,
    oldest_age_days  INTEGER NOT NULL,
    avg_age_days     NUMERIC(8,1) NOT NULL,
    last_receipt     DATE,
    as_of            DATE    NOT NULL,
    data_source      TEXT    NOT NULL DEFAULT 'POC_SYNTHETIC',
    PRIMARY KEY (product_id, region)
);

CREATE TABLE IF NOT EXISTS inv_purchase_order (
    id          UUID PRIMARY KEY,
    product_id  UUID    NOT NULL,
    region      TEXT    NOT NULL,
    qty         INTEGER NOT NULL,
    ordered_on  DATE    NOT NULL,
    eta         DATE    NOT NULL,
    status      TEXT    NOT NULL DEFAULT 'OPEN',
    data_source TEXT    NOT NULL DEFAULT 'POC_SYNTHETIC'
);
CREATE INDEX IF NOT EXISTS ix_inv_po_product ON inv_purchase_order (product_id, status);

CREATE TABLE IF NOT EXISTS inv_model_run (
    id               UUID PRIMARY KEY,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    as_of            DATE        NOT NULL,
    model_name       TEXT        NOT NULL,                -- the SELECTED model
    model_version    TEXT        NOT NULL,
    training_start   DATE        NOT NULL,
    training_end     DATE        NOT NULL,
    horizon_days     INTEGER     NOT NULL,
    n_series         INTEGER     NOT NULL,
    interval_scale   DOUBLE PRECISION NOT NULL,           -- calibrated width multiplier of the 80% interval
    metrics          JSONB       NOT NULL,                -- per candidate model: wape/mae/rmse/mape/bias/coverage
    features         JSONB       NOT NULL,
    data_source      TEXT        NOT NULL,
    duration_ms      INTEGER,
    is_current       BOOLEAN     NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS inv_forecast (
    run_id         UUID    NOT NULL REFERENCES inv_model_run (id) ON DELETE CASCADE,
    product_id     UUID    NOT NULL,
    model_name     TEXT    NOT NULL,
    model_version  TEXT    NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    training_start DATE,
    training_end   DATE,
    status         TEXT    NOT NULL,                      -- OK | INSUFFICIENT_DATA
    reason         TEXT,
    daily_mean     DOUBLE PRECISION[],                    -- day 1..horizon after as_of
    daily_lo       DOUBLE PRECISION[],
    daily_hi       DOUBLE PRECISION[],
    sigma_daily    DOUBLE PRECISION,                      -- one-day forecast error std from the backtest
    history_days   INTEGER,
    wape_backtest  DOUBLE PRECISION,
    PRIMARY KEY (run_id, product_id)
);

CREATE TABLE IF NOT EXISTS inv_event_impact (
    run_id      UUID NOT NULL REFERENCES inv_model_run (id) ON DELETE CASCADE,
    event_id    TEXT NOT NULL,
    sport       TEXT NOT NULL,
    category    TEXT NOT NULL,
    uplift      DOUBLE PRECISION NOT NULL,                -- multiplier on baseline demand during the event
    uplift_lo   DOUBLE PRECISION NOT NULL,
    uplift_hi   DOUBLE PRECISION NOT NULL,
    n_events    INTEGER NOT NULL,
    n_products  INTEGER NOT NULL,
    basis       TEXT    NOT NULL,                         -- HISTORICAL | POC_ASSUMPTION
    detail      JSONB   NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (run_id, event_id, category)
);

CREATE TABLE IF NOT EXISTS inv_elasticity (
    run_id      UUID NOT NULL REFERENCES inv_model_run (id) ON DELETE CASCADE,
    category    TEXT NOT NULL,
    elasticity  DOUBLE PRECISION NOT NULL,                -- negative: % demand change per % price change
    elasticity_lo DOUBLE PRECISION NOT NULL,
    elasticity_hi DOUBLE PRECISION NOT NULL,
    pull_forward DOUBLE PRECISION NOT NULL,               -- share of promotion uplift borrowed from the 14 days after it
    n_promo_days INTEGER NOT NULL,
    basis       TEXT    NOT NULL,                         -- HISTORICAL | POC_ASSUMPTION
    PRIMARY KEY (run_id, category)
);

-- One row per product and scenario (BASELINE or EVENT:<id>): stock risk + replenishment + overstock, all deterministic.
CREATE TABLE IF NOT EXISTS inv_assessment (
    run_id          UUID NOT NULL REFERENCES inv_model_run (id) ON DELETE CASCADE,
    product_id      UUID NOT NULL,
    scenario        TEXT NOT NULL,
    as_of           DATE NOT NULL,
    status          TEXT NOT NULL,                        -- OK | INSUFFICIENT_DATA | MISSING_LEAD_TIME
    reason          TEXT,
    on_hand         INTEGER,
    incoming        INTEGER,
    lead_time_days  INTEGER,
    daily_demand    DOUBLE PRECISION,
    forecast_7      DOUBLE PRECISION,
    forecast_30     DOUBLE PRECISION,
    forecast_90     DOUBLE PRECISION,
    days_of_cover   DOUBLE PRECISION,                     -- NULL = does not run out within the horizon
    stockout_date   DATE,
    p_stockout_lt   DOUBLE PRECISION,
    safety_stock    INTEGER,
    reorder_point   INTEGER,
    risk_level      TEXT,                                 -- HIGH | MEDIUM | LOW
    reorder_qty     INTEGER,
    order_by        DATE,
    arrival_date    DATE,
    priority        TEXT,                                 -- HIGH | MEDIUM | LOW | NONE
    excess_units    INTEGER,
    excess_value    NUMERIC(14,2),
    coverage_days   DOUBLE PRECISION,
    overstock_level TEXT,                                 -- HIGH | MEDIUM | NONE
    health_class    TEXT,                                 -- Healthy | Watch | Slow Moving | Critical Aging
    age_days        INTEGER,
    detail          JSONB NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (run_id, product_id, scenario)
);
CREATE INDEX IF NOT EXISTS ix_inv_assessment_risk ON inv_assessment (run_id, scenario, risk_level);

CREATE TABLE IF NOT EXISTS inv_scenario_run (
    id          UUID PRIMARY KEY,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    run_id      UUID,
    actor_hash  TEXT,
    params      JSONB NOT NULL,
    results     JSONB NOT NULL
);

CREATE TABLE IF NOT EXISTS inv_audit (
    id             BIGSERIAL PRIMARY KEY,
    ts             TIMESTAMPTZ NOT NULL DEFAULT now(),
    actor_hash     TEXT,
    action         TEXT NOT NULL,                         -- TRAIN | FORECAST | SCENARIO | QUERY | SEED | DENIED
    detail         JSONB NOT NULL DEFAULT '{}'::jsonb,    -- no secrets, no personal data
    correlation_id TEXT
);

CREATE TABLE IF NOT EXISTS inv_dq_report (
    id         UUID PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    report     JSONB NOT NULL
);

-- Share of each product's recent baseline demand by region (used to split forecasts, stock risk and transfers by region).
CREATE TABLE IF NOT EXISTS inv_region_share (
    run_id     UUID NOT NULL REFERENCES inv_model_run (id) ON DELETE CASCADE,
    product_id UUID NOT NULL,
    region     TEXT NOT NULL,
    share      DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (run_id, product_id, region)
);
